#include <bits/stdc++.h>

using namespace std;
using ll = int64_t;

const string kPrefix = "IAO'";
const ll kStart = 1989;
const ll kBuben = 100000;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  unordered_map<string, string> reses;
  reses.reserve(kBuben);

  for (ll year = kStart; year <= kBuben; ++year) {
    string s = to_string(year);
    for (size_t len = 1; len <= s.size(); ++len) {
      string suffix = s.substr(s.size() - len);
      if (!reses.count(suffix)) {
        reses.emplace(suffix, s);
        break;
      }
    }
  }

  int n;
  cin >> n;

  while (n--) {
    string name;
    cin >> name;
    name = name.substr(kPrefix.size());

    auto it = reses.find(name);
    if (it != reses.end()) {
      cout << it->second << '\n';
    } else {
      if (!name.empty() && name[0] == '0') {
        name = "1" + name;
      }
      cout << name << '\n';
    }
  }

  return 0;
}

