#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    constexpr int64 START = 1989;
    constexpr int64 LIMIT = 1000000;
    const string PREFIX = "IAO'";

    int n;
    cin >> n;

    while (n--) {
        string input;
        cin >> input;
        string name = input.substr(PREFIX.size());

        bool found = false;
        int64 year = 0;

        if (name.size() <= 6) {
            int64 value = 0;
            int64 power = 1;

            for (char c : name) {
                value = value * 10 + (c - '0');
                power *= 10;
            }

            year = value;
            if (year < START) {
                year += ((START - year + power - 1) / power) * power;
            }

            int64 lower = START;
            if (name.size() > 1) {
                lower += power / 10;
            }

            found = year >= lower && year <= LIMIT;
        }

        if (found) {
            cout << year << '\n';
        } else {
            if (!name.empty() && name[0] == '0') {
                name = "1" + name;
            }
            cout << name << '\n';
        }
    }

    return 0;
}

