#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    while (n--) {
        string name;
        cin >> name;
        name = name.substr(4);

        cpp_int assigned = 1988;
        cpp_int place = 1;
        cpp_int value = 0;

        for (int i = static_cast<int>(name.size()) - 1; i >= 0; --i) {
            value += (name[i] - '0') * place;
            cpp_int modulus = place * 10;
            cpp_int lower = assigned + 1;

            if (lower < 1989) lower = 1989;
            if (lower < place) lower = place;

            cpp_int delta = (value - lower % modulus + modulus) % modulus;
            assigned = lower + delta;
            place = modulus;
        }

        cout << assigned << '\n';
    }

    return 0;
}

